const raw = $json.text ?? $json.response ?? $json.output ?? JSON.stringify($json);
let creative; try { creative = JSON.parse(raw); } catch { throw new Error('Creative Scriptwriter returned invalid JSON'); }
const source = $node['Preparar paquete editorial'].json;
const editorialPackage = source.editorial_package;
if (!['READY', 'INSUFFICIENT_MATERIAL'].includes(creative.status)) throw new Error('Invalid creative status');
if (creative.format !== editorialPackage.format || typeof creative.script !== 'string') throw new Error('Creative format or script is invalid');
const actualWordCount = creative.script.trim() ? creative.script.trim().split(/\s+/).length : 0;
if (creative.status === 'READY') {
  if (actualWordCount < 160 || actualWordCount > 300) throw new Error('Creative script must contain 160–300 spoken words');
  if (creative.word_count !== actualWordCount) throw new Error('Creative word_count does not match narration');
  if (!Number.isFinite(creative.estimated_duration_seconds) || creative.estimated_duration_seconds < 60 || creative.estimated_duration_seconds > 120) throw new Error('Invalid creative duration');
  const expectedStories = editorialPackage.stories.map((story) => story.story_id);
  const actualStories = (creative.story_coverage ?? []).map((story) => story.story_id);
  if (JSON.stringify(actualStories) !== JSON.stringify(expectedStories)) throw new Error('Creative story coverage must preserve editorial order');
} else if (creative.script || creative.word_count !== 0) throw new Error('Insufficient creative result must not contain narration');
return [{ json: { job_type: source.job_type, subject_id: source.subject_id, creative, script_text: creative.script } }];

const isDaily = $json.job_type === 'daily';
const subjectId = Number($json.subject_id);
if (!Number.isSafeInteger(subjectId) || subjectId < 1) throw new Error('Invalid script subject');
const revision = String($execution.id ?? Date.now());
const scriptUri = isDaily ? `/n8n-youtube-automation/Honi-News/Daily-News/Scripts/queue-${subjectId}-${revision}.md` : `/n8n-youtube-automation/Honi-News/Individual-News/Scripts/article-${subjectId}-${revision}.md`;
const sqlLiteral = (value) => "'" + String(value).replaceAll("'", "''") + "'";
const jobType = isDaily ? 'daily' : 'individual';
const model = 'gemini/gemini-3.8-flash';
const creativeJson = JSON.stringify($json.creative);
const yaml = (value) => JSON.stringify(String(value ?? ''));
const markdown = ['---', `title: ${yaml($json.creative.title)}`, `format: ${yaml($json.creative.format)}`, `status: ${yaml($json.creative.status)}`, 'agent: "Honi Creative Scriptwriter"', 'prompt_version: "honi_creative_scriptwriter@v1"', `model: ${yaml(model)}`, `generated_at_utc: ${yaml(new Date().toISOString())}`, '---', '', `# ${$json.creative.title}`, '', $json.creative.script, ''].join('\n');
const persistenceQuery = `WITH saved_daily AS (INSERT INTO daily_news_scripts (queue_id,prompt_version,model,script_text,script_uri,status,raw_response,approval_status,approved_at_utc,production_status,production_prompt_version,production_model,production_response,production_uri) SELECT ${subjectId},'honi_creative_scriptwriter@v1',${sqlLiteral(model)},${sqlLiteral($json.script_text)},${sqlLiteral(scriptUri)},CASE WHEN ${sqlLiteral(creativeJson)}::jsonb->>'status'='READY' THEN 'ready' ELSE 'failed' END,${sqlLiteral(creativeJson)}::jsonb,'pending',NULL,'blocked',NULL,NULL,NULL,NULL WHERE ${sqlLiteral(jobType)}='daily' ON CONFLICT (queue_id) DO UPDATE SET prompt_version=EXCLUDED.prompt_version,model=EXCLUDED.model,script_text=EXCLUDED.script_text,script_uri=EXCLUDED.script_uri,status=EXCLUDED.status,raw_response=EXCLUDED.raw_response,approval_status='pending',approved_at_utc=NULL,production_status='blocked',production_prompt_version=NULL,production_model=NULL,production_response=NULL,production_uri=NULL,updated_at_utc=now() RETURNING id), saved_individual AS (INSERT INTO individual_scripts (article_id,classification_id,prompt_version,model,script_text,script_uri,status,raw_response,approval_status,approved_at_utc,production_status,production_prompt_version,production_model,production_response,production_uri) SELECT job.article_id,job.classification_id,'honi_creative_scriptwriter@v1',${sqlLiteral(model)},${sqlLiteral($json.script_text)},${sqlLiteral(scriptUri)},CASE WHEN ${sqlLiteral(creativeJson)}::jsonb->>'status'='READY' THEN 'ready' ELSE 'failed' END,${sqlLiteral(creativeJson)}::jsonb,'pending',NULL,'blocked',NULL,NULL,NULL,NULL FROM individual_script_jobs job WHERE ${sqlLiteral(jobType)}='individual' AND job.article_id=${subjectId} ON CONFLICT (article_id) DO UPDATE SET classification_id=EXCLUDED.classification_id,prompt_version=EXCLUDED.prompt_version,model=EXCLUDED.model,script_text=EXCLUDED.script_text,script_uri=EXCLUDED.script_uri,status=EXCLUDED.status,raw_response=EXCLUDED.raw_response,approval_status='pending',approved_at_utc=NULL,production_status='blocked',production_prompt_version=NULL,production_model=NULL,production_response=NULL,production_uri=NULL,updated_at_utc=now() RETURNING id), updated_daily_job AS (UPDATE daily_news_script_jobs SET status=CASE WHEN ${sqlLiteral(creativeJson)}::jsonb->>'status'='READY' THEN 'scripted' ELSE 'failed' END,lock_token=NULL,locked_at_utc=NULL,updated_at_utc=now() WHERE ${sqlLiteral(jobType)}='daily' AND queue_id=${subjectId}), updated_daily_queue AS (UPDATE daily_news_queues SET status=CASE WHEN ${sqlLiteral(creativeJson)}::jsonb->>'status'='READY' THEN 'scripted' ELSE 'failed' END,updated_at_utc=now() WHERE ${sqlLiteral(jobType)}='daily' AND id=${subjectId}), updated_individual_job AS (UPDATE individual_script_jobs SET status=CASE WHEN ${sqlLiteral(creativeJson)}::jsonb->>'status'='READY' THEN 'scripted' ELSE 'failed' END,lock_token=NULL,locked_at_utc=NULL,updated_at_utc=now() WHERE ${sqlLiteral(jobType)}='individual' AND article_id=${subjectId}) SELECT id FROM saved_daily UNION ALL SELECT id FROM saved_individual;`;
return [{ json: { ...$json, script_uri: scriptUri, script_markdown: markdown, persistence_query: persistenceQuery } }];

const raw = $json.text ?? $json.response ?? $json.output ?? JSON.stringify($json);
let production; try { production = JSON.parse(raw); } catch { throw new Error('Production Director returned invalid JSON'); }
const creativeState = $node['Validar guión creativo'].json;
if (production.status !== 'READY' || !Array.isArray(production.beats)) throw new Error('Invalid production contract');
if (production.title !== creativeState.creative.title || production.format !== creativeState.creative.format) throw new Error('Production metadata changed');
const spoken = production.beats.map((beat) => beat.spoken_text).join(' ');
if (spoken.replace(/\s+/g, ' ').trim() !== creativeState.creative.script.replace(/\s+/g, ' ').trim()) throw new Error('Production Director rewrote approved narration');
const prefix = creativeState.job_type === 'daily' ? '/n8n-youtube-automation/Honi-News/Daily-News/Scripts' : '/n8n-youtube-automation/Honi-News/Individual-News/Scripts';
return [{ json: { production, creative: creativeState.creative, production_uri: `${prefix}/production-${creativeState.subject_id}-${$execution.id}.json`, production_json: JSON.stringify(production, null, 2) } }];
